mapper.select:
SELECT m.id, p.id 'project.id', p.short_name 'project.short_name', p.serial_number 'project.contract_no', mo.id 'monomer.id', mo.name 'monomer.name', m.file_id, m.file_name, m.translate_status, m.file_thumbnail, m.file_tiny_thumbnail, m.create_time, m.update_time, m.integration_status, u.name AS create_user_name, m.edition, m.model_type, m.import_mode FROM plan_monomer mo LEFT JOIN contract_project p ON p.id = mo.project_id LEFT JOIN bim_model m ON mo.id = m.monomer_id AND m.import_mode = #{importMode} and m.bool_delete_enum = 0 LEFT JOIN sys_user u ON u.id = m.create_user_id
m.bool_delete_enum = 0 AND m.area_id is NULL
AND mo.project_id = #{projectId}
AND mo.id = #{monomerId}

SELECT m.id, p.id 'project.id', p.short_name 'project.short_name', p.serial_number 'project.contract_no', area.id 'area.id', area.name 'area.name', m.file_id, m.file_name, m.translate_status, m.file_thumbnail, m.file_tiny_thumbnail, m.create_time, m.update_time, m.integration_status, u.name AS create_user_name, m.edition, m.model_type, m.file_size, m.import_mode FROM plan_area area LEFT JOIN contract_project p ON p.id = area.project_id LEFT JOIN bim_model m ON area.id = m.area_id AND m.import_mode = #{importMode} AND m.bool_delete_enum = 0
AND m.monomer_id = #{monomerId}
LEFT JOIN sys_user u ON u.id = m.create_user_id
AND area.project_id = #{projectId}
AND area.monomer_id = #{monomerId}
and area.id in
#{areaId}
order by area.create_time

SELECT
    IFNULL(SUM(success_quantity) ,0)
FROM
    `bim_model`
WHERE 1=1

    AND monomer_id=#{monomerId}


    AND import_mode=#{importMode}


    AND area_id=#{areaId}
